1	// ───────────────────────────────────────────────────────────────────
2	// MODULE: Packet Purpose
3	// ───────────────────────────────────────────────────────────────────
4	// Reads why a spec packet exists from its own documents, so a surface that
5	// rebuilds context after a compaction or a hop can repeat the purpose and not
6	// only the files and the next step. Every read fails soft: a missing or
7	// unreadable document yields null, never an exception.
8	
9	import * as fs from 'node:fs';
10	import * as path from 'node:path';
11	
12	import { isPhaseParent } from './is-phase-parent.js';
13	
14	// ───────────────────────────────────────────────────────────────────
15	// 1. TYPES & CONSTANTS
16	// ───────────────────────────────────────────────────────────────────
17	
18	/** Where the purpose text came from: the packet, an enclosing phase parent or the packet's goal.md Objective. */
19	export type PacketPurposeSource = 'packet' | 'ancestor' | 'goal';
20	
21	/** One resolved purpose sentence and the folder it was read from. */
22	export interface PacketPurpose {
23	  /** The first sentence of the purpose, whitespace-collapsed and length-capped. */
24	  text: string;
25	  /** Which document supplied the text. */
26	  source: PacketPurposeSource;
27	  /** Absolute path of the folder whose spec.md or goal.md held the text. */
28	  folder: string;
29	}
30	
31	// The phase-parent scaffold has written this sentence, in two wordings, in
32	// place of a purpose. It describes the document layout, not the work, so it
33	// never counts as one.
34	const SCAFFOLD_PARENT_PURPOSE = /^Keep parent documentation lean while child phases own detailed plans\b/;
35	// One sentence has to fit even a pressure-shrunk recovery budget.
36	const MAX_PURPOSE_CHARS = 300;
37	const MAX_ANCESTOR_DEPTH = 8;
38	
39	// ───────────────────────────────────────────────────────────────────
40	// 2. TEXT EXTRACTION
41	// ───────────────────────────────────────────────────────────────────
42	
43	function readTextFile(filePath: string): string | null {
44	  try {
45	    return fs.readFileSync(filePath, 'utf8');
46	  } catch {
47	    return null;
48	  }
49	}
50	
51	/** The first paragraph under the `### Purpose` heading, skipping comment lines. */
52	function extractPurposeParagraph(markdown: string): string {
53	  const lines = markdown.split(/\r?\n/);
54	  const start = lines.findIndex((line) => /^###\s+Purpose\s*$/.test(line.trim()));
55	  if (start < 0) return '';
56	  const body: string[] = [];
57	  for (const raw of lines.slice(start + 1)) {
58	    const line = raw.trim();
59	    if (line.startsWith('#') || line.startsWith('<!-- /ANCHOR') || line.startsWith('>')) break;
60	    if (line.startsWith('<!--')) continue;
61	    if (line === '') {
62	      if (body.length > 0) break;
63	      continue;
64	    }
65	    body.push(line);
66	  }
67	  return body.join(' ');
68	}
69	
70	function extractGoalObjective(markdown: string): string {
71	  return markdown.match(/^\*\*Objective:\*\*\s*(.+)$/m)?.[1] ?? '';
72	}
73	
74	/**
75	 * The first sentence of authored text, or null for a template token, a
76	 * bracketed prompt, UNKNOWN or the scaffold's layout sentence.
77	 */
78	function authoredSentence(raw: string): string | null {
79	  const text = raw.replace(/<!--[\s\S]*?-->/g, ' ').replace(/\s+/g, ' ').trim();
80	  if (!text || SCAFFOLD_PARENT_PURPOSE.test(text)) return null;
81	  if (text.includes('[YOUR_VALUE_HERE') || /^\[[^\]]*\]$/.test(text) || /^unknown\.?$/i.test(text)) return null;
82	  const sentence = text.match(/^.+?[.!?](?=\s|$)/)?.[0] ?? text;
83	  return sentence.length <= MAX_PURPOSE_CHARS
84	    ? sentence
85	    : `${sentence.slice(0, MAX_PURPOSE_CHARS - 3).trimEnd()}...`;
86	}
87	
88	function purposeIn(folder: string): string | null {
89	  const markdown = readTextFile(path.join(folder, 'spec.md'));
90	  return markdown === null ? null : authoredSentence(extractPurposeParagraph(markdown));
91	}
92	
93	// ───────────────────────────────────────────────────────────────────
94	// 3. RESOLUTION
95	// ───────────────────────────────────────────────────────────────────
96	
97	/**
98	 * Resolve the one-sentence purpose of a spec packet.
99	 *
100	 * Reads the packet's own `### Purpose` first. When that is empty or a
101	 * placeholder, walks up through enclosing phase parents that carry a spec.md
102	 * and takes the nearest authored purpose. When neither exists, takes the
103	 * packet's goal.md Objective. Returns null when nothing authored exists or a
104	 * read fails.
105	 *
106	 * @param specFolderAbsPath - Absolute path to the spec packet folder
107	 * @returns The purpose sentence with its source and folder, or null
108	 */
109	export function resolvePacketPurpose(specFolderAbsPath: string): PacketPurpose | null {
110	  try {
111	    const folder = path.resolve(specFolderAbsPath);
112	    const own = purposeIn(folder);
113	    if (own) return { text: own, source: 'packet', folder };
114	
115	    let current = folder;
116	    for (let depth = 0; depth < MAX_ANCESTOR_DEPTH; depth += 1) {
117	      const parent = path.dirname(current);
118	      if (parent === current) break;
119	      if (!fs.existsSync(path.join(parent, 'spec.md')) || !isPhaseParent(parent)) break;
120	      const inherited = purposeIn(parent);
121	      if (inherited) return { text: inherited, source: 'ancestor', folder: parent };
122	      current = parent;
123	    }
124	
125	    const goal = readTextFile(path.join(folder, 'goal.md'));
126	    const objective = goal === null ? null : authoredSentence(extractGoalObjective(goal));
127	    return objective ? { text: objective, source: 'goal', folder } : null;
128	  } catch {
129	    return null;
130	  }
131	}
132	
133	/** Render a resolved purpose as one line, naming the parent folder when the text is inherited. */
134	export function formatPacketPurpose(purpose: PacketPurpose, projectRoot: string): string {
135	  if (purpose.source === 'ancestor') {
136	    const parentFolder = path.relative(projectRoot, purpose.folder).split(path.sep).join('/');
137	    return `Parent purpose (${parentFolder}): ${purpose.text}`;
138	  }
139	  if (purpose.source === 'goal') return `Goal objective: ${purpose.text}`;
140	  return `Purpose: ${purpose.text}`;
141	}
142

